INSERT INTO `posts` VALUES (1,1,'Chào mừng mọi người đến với mạng xã hội Socialita! Nơi kết nối thật và chia sẻ là chính bạn. Rất vui được đồng hành cùng cộng đồng công nghệ hôm nay! 🚀✨',NULL,'2026-09-28 01:30:00','Hà Nội','linear-gradient(180deg, #18191a 0%, #242526 50%, #7a1d26 100%)','2026-09-28 03:41:02','active','public'),(3,6,'Chuyến đi Mù Cang Chải ngắm mùa vàng bậc thang đẹp như một bức tranh thuỷ mặc! Đất nước mình còn bao nhiêu cảnh đẹp đang chờ khám phá 🌾⛰️',NULL,'2026-09-27 09:45:00','Yên Bái','linear-gradient(135deg, #4a1d4b 0%, #1f0d29 100%)','2026-09-28 03:41:02','active','public'),(4,7,'Vừa hoàn thiện xong concept giao diện tối giản cho Socialita. Tông đỏ đen sang trọng, rất mong nhận được góp ý của anh em! 🎨📱',NULL,'2026-09-26 11:20:00','Hà Nội','linear-gradient(135deg, #2b2d3d 0%, #1c1d2b 100%)','2026-09-28 03:41:02','active','public'),(5,3,'Bán tài khoản game giá rẻ, ib zalo 0987654xxx... liên hệ ngay kẻo hết ưu đãi sốc hôm nay!!',NULL,'2026-09-28 00:00:00','Toàn quốc','linear-gradient(180deg, #18191a 0%, #242526 50%, #7a1d26 100%)','2026-09-28 03:41:02','active','public'),(8,10,'Xin ch�o Socialita! D�y l� b�i vi?t ki?m th? k?t n?i Front-end & Back-end t? t�i kho?n m?i.',NULL,'2026-10-04 04:00:08','S�i G�n','linear-gradient(180deg, #18191a 0%, #242526 50%, #7a1d26 100%)','2026-10-04 04:00:08','active','public'),(9,1,'Bài viết kiểm thử tự động kèm ảnh và check-in Đà Lạt 🌸','https://images.unsplash.com/photo-1506744038136-46273834b3fb','2026-10-04 04:27:56','Đà Lạt, Lâm Đồng','linear-gradient(180deg, #18191a 0%, #242526 50%, #7a1d26 100%)','2026-10-04 04:27:56','active','public'),(10,1,'Bài viết kiểm thử tự động kèm ảnh và check-in Đà Lạt 🌸','https://images.unsplash.com/photo-1506744038136-46273834b3fb','2026-10-04 04:29:15','Đà Lạt, Lâm Đồng','linear-gradient(180deg, #18191a 0%, #242526 50%, #7a1d26 100%)','2026-10-04 04:29:15','active','public'),(11,1,'Hello, test01','http://localhost:8080/uploads/post-1791088398894-438529577.jpg','2026-10-04 04:33:18','Hà Nội',NULL,'2026-10-04 04:33:18','active','public'),(12,11,'Hello','[\"http://localhost:8080/uploads/post-1791640011040-741635974.jpg\",\"http://localhost:8080/uploads/post-1791640011042-894456313.jpg\",\"http://localhost:8080/uploads/post-1791640011043-283627644.jpg\"]','2026-10-10 13:46:51',NULL,NULL,'2026-10-10 13:46:51','active','public'),(13,2,'Test','http://localhost:8080/uploads/post-1791640319550-105837788.png','2026-10-10 13:51:59',NULL,NULL,'2026-10-10 13:51:59','active','public'),(14,1,'Bi mat chi minh toi',NULL,'2026-10-18 04:48:56',NULL,NULL,'2026-10-18 04:48:56','active','public'),(15,1,'Bi mat chi minh toi moi',NULL,'2026-10-18 04:49:49',NULL,NULL,'2026-10-18 04:49:49','active','private'),(16,1,'Bai viet danh rieng cho ban be',NULL,'2026-10-18 04:50:15',NULL,NULL,'2026-10-18 04:50:15','active','friends'),(17,1,'Cuối tuần lang thang cà phê đường Phan Đình Phùng, ngắm phố xá Hà Nội vào thu dịu dàng và bình yên biết bao! Chúc cả nhà tuần mới ngập tràn năng lượng nhé. 🍂☕ #HanoiAutumn #CoffeeTime','https://images.unsplash.com/photo-1509042239860-f550ce710b93?w=800&auto=format&fit=crop','2026-11-07 12:10:03','Phan Đình Phùng, Ba Đình, Hà Nội',NULL,'2026-11-07 15:10:03','active','public'),(18,2,'Chuyến trekking Fansipan 2 ngày 1 đêm đáng nhớ cùng nhóm bạn! Chạm tay vào đỉnh chóp 3.143m ngắm biển mây ngút ngàn, cảm giác mọi mệt mỏi tan biến hết. ⛰️☁️ #Fansipan #Trekking #VietnamTravel','[\"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?w=800&auto=format&fit=crop\",\"https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800&auto=format&fit=crop\"]','2026-11-07 08:10:03','Đỉnh Fansipan, Sa Pa',NULL,'2026-11-07 15:10:03','active','public'),(19,3,'Vừa hoàn thành dự án web sau 3 tuần code xuyên màn đêm! Cảm giác deploy thành công mọi tính năng không một bug thật sự giải tỏa. Tự thưởng cho bản thân một bữa lẩu thôi nào! 💻🚀🎉 #WebDev #CodingLife',NULL,'2026-11-07 04:10:03','Đại học Bách Khoa','linear-gradient(135deg, #1e3a8a 0%, #3b82f6 50%, #06b6d4 100%)','2026-11-07 15:10:03','active','public'),(20,4,'Hoàng hôn Hồ Tây chiều nay đẹp đến nao lòng. Cứ mỗi lần mệt mỏi lại ra đây hóng gió ngắm mặt trời lặn là thấy tâm trạng nhẹ nhõm hẳn. 🌅🚲 #SunsetLovers #WestLake','https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800&auto=format&fit=crop','2026-11-07 00:10:03','Hồ Tây, Hà Nội',NULL,'2026-11-07 15:10:03','active','public'),(21,5,'Check-in Đà Lạt mùa hoa dã quỳ nở rộ! Không khí se se lạnh 17 độ C cùng ly sữa đậu nành nóng hổi thì còn gì tuyệt vời hơn. Ai chuẩn bị đi Đà Lạt điểm danh nào! 🌼🌸🧣 #DaLat #TravelVietnam','[\"https://images.unsplash.com/photo-1518495973542-4542c06a5843?w=800&auto=format&fit=crop\",\"https://images.unsplash.com/photo-1470246973918-29a93221c455?w=800&auto=format&fit=crop\",\"https://images.unsplash.com/photo-1519681393784-d120267933ba?w=800&auto=format&fit=crop\"]','2026-11-06 19:10:03','Đà Lạt, Lâm Đồng',NULL,'2026-11-07 15:10:03','active','public'),(22,6,'Sài Gòn về đêm luôn lung linh và tràn đầy sức sống. Dạo phố đi bộ Nguyễn Huệ ngắm đèn xe nhộn nhịp, tự nhiên thấy yêu thành phố này lạ kỳ. 🏙️✨ #SaigonByNight #NguyenHue','https://images.unsplash.com/photo-1519501025264-65ba15a82390?w=800&auto=format&fit=crop','2026-11-06 11:10:03','Phố đi bộ Nguyễn Huệ, Quận 1',NULL,'2026-11-07 15:10:03','active','public'),(23,7,'Một góc làm việc gọn gàng sẽ giúp tăng 200% hiệu suất làm việc! Hôm nay vừa setup thêm chiếc màn hình mới và vài chậu cây xanh nhỏ xinh. Mọi người thấy thế nào? 🪴🖥️ #DeskSetup #WorkspaceInspiration','https://images.unsplash.com/photo-1518455027359-f3f8164ba6bd?w=800&auto=format&fit=crop','2026-11-06 07:10:03','Home Workspace',NULL,'2026-11-07 15:10:03','active','friends'),(24,9,'“Hành trình vạn dặm bắt đầu từ một bước chân.” Cuốn sách mới đọc xong cuối tuần thật sự truyền cảm hứng để bắt đầu những mục tiêu mới cho tháng tới. 📖💡 #BookReview #SelfGrowth',NULL,'2026-11-06 04:10:03','Nhã Nam Book Nook','linear-gradient(135deg, #7c3aed 0%, #db2777 100%)','2026-11-07 15:10:03','active','public'),(25,10,'Chuyến roadtrip khám phá bán đảo Sơn Trà và cung đường đèo Hải Vân hùng vĩ! Cảm giác phóng xe máy giữa một bên là núi cao, một bên là biển xanh bao la thật khó tả. 🛵🌊 #HaiVanPass #DaNang','[\"https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800&auto=format&fit=crop\",\"https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800&auto=format&fit=crop\"]','2026-11-05 20:10:03','Đèo Hải Vân, Đà Nẵng',NULL,'2026-11-07 15:10:03','active','public'),(26,11,'Bữa cơm gia đình ấm cúng cuối tuần cùng ba mẹ. Đi xa mới thấy nhớ những món ăn mẹ nấu biết bao, sơn hào hải vị ngoài kia chẳng thể sánh bằng. ❤️🍲 #FamilyFirst #HomeSweetHome','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?w=800&auto=format&fit=crop','2026-11-05 17:10:03','Hải Phòng',NULL,'2026-11-07 15:10:03','active','friends'),(27,12,'Chúc mừng team vừa giành giải Nhất cuộc thi Hackathon sinh viên 2026! 48 giờ không ngủ, uống 10 ly cà phê nhưng kết quả hoàn toàn xứng đáng. Tự hào về mọi người nhiều lắm! 🏆🥇🎉 #Hackathon #TeamWork','https://images.unsplash.com/photo-1531482615713-2afd69097998?w=800&auto=format&fit=crop','2026-11-05 13:10:03','Trung tâm Đổi mới Sáng tạo Quốc gia (NIC)',NULL,'2026-11-07 15:10:03','active','public'),(28,13,'Tập gym 5 buổi/tuần duy trì được 6 tháng rồi, sức bền và tinh thần thay đổi rõ rệt. Không có con đường tắt, chỉ có sự kiên trì mỗi ngày. Let’s do this! 🏋️‍♂️🔥 #GymMotivation #HealthyLifestyle','https://images.unsplash.com/photo-1534438327276-14e5300c3a48?w=800&auto=format&fit=crop','2026-11-05 06:10:03','Elite Fitness',NULL,'2026-11-07 15:10:03','active','public'),(29,14,'Thưởng thức âm nhạc acoustic tại quán quen. Giữa thành phố bộn bề, có một nốt trầm lắng nghe giai điệu mộc mạc thế này là đủ an yên rồi. 🎶🎸 #AcousticNight #ChillVibes',NULL,'2026-11-05 03:10:03','Phố Cổ Hà Nội','linear-gradient(135deg, #0f172a 0%, #1e293b 50%, #334155 100%)','2026-11-07 15:10:03','active','public'),(30,15,'Hội An về đêm rực rỡ sắc màu đèn lồng và dòng sông Hoài thơ mộng. Thả một ngọn đèn hoa đăng cầu bình an và may mắn cho tất cả những người thân yêu. 🏮✨ #HoiAnAncientTown #VietnamTravel','https://images.unsplash.com/photo-1528127269322-539801943592?w=800&auto=format&fit=crop','2026-11-04 20:10:03','Phố cổ Hội An, Quảng Nam',NULL,'2026-11-07 15:10:03','active','public'),(31,16,'Chào đón thành viên 4 chân mới của gia đình! Em cún Poodle siêu nghịch ngợm tên Bơ, vừa về nhà đã cắn hỏng đôi dép của mình rồi 🐶❤️ Ai nuôi cún cho mình xin tips chăm sóc với! #PuppyLove #Poodle','https://images.unsplash.com/photo-1543466835-00a7907e9de1?w=800&auto=format&fit=crop','2026-11-04 15:10:03','TP. Hồ Chí Minh',NULL,'2026-11-07 15:10:03','active','public'),(32,6,'Cuối tuần lang thang cà phê đường Phan Đình Phùng, ngắm phố xá Hà Nội vào thu dịu dàng và bình yên biết bao! Chúc cả nhà tuần mới ngập tràn năng lượng nhé. 🍂☕ #HanoiAutumn #CoffeeTime','https://images.unsplash.com/photo-1509042239860-f550ce710b93?w=800&auto=format&fit=crop','2026-11-06 15:10:03','Phan Đình Phùng, Ba Đình, Hà Nội',NULL,'2026-11-07 15:10:03','active','public'),(33,7,'Chuyến trekking Fansipan 2 ngày 1 đêm đáng nhớ cùng nhóm bạn! Chạm tay vào đỉnh chóp 3.143m ngắm biển mây ngút ngàn, cảm giác mọi mệt mỏi tan biến hết. ⛰️☁️ #Fansipan #Trekking #VietnamTravel','[\"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?w=800&auto=format&fit=crop\",\"https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800&auto=format&fit=crop\"]','2026-11-05 15:10:03','Đỉnh Fansipan, Sa Pa',NULL,'2026-11-07 15:10:03','active','public'),(34,9,'Vừa hoàn thành dự án web sau 3 tuần code xuyên màn đêm! Cảm giác deploy thành công mọi tính năng không một bug thật sự giải tỏa. Tự thưởng cho bản thân một bữa lẩu thôi nào! 💻🚀🎉 #WebDev #CodingLife',NULL,'2026-11-04 15:10:03','Đại học Bách Khoa','linear-gradient(135deg, #1e3a8a 0%, #3b82f6 50%, #06b6d4 100%)','2026-11-07 15:10:03','active','public'),(35,10,'Hoàng hôn Hồ Tây chiều nay đẹp đến nao lòng. Cứ mỗi lần mệt mỏi lại ra đây hóng gió ngắm mặt trời lặn là thấy tâm trạng nhẹ nhõm hẳn. 🌅🚲 #SunsetLovers #WestLake','https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800&auto=format&fit=crop','2026-11-03 15:10:03','Hồ Tây, Hà Nội',NULL,'2026-11-07 15:10:03','active','public'),(36,11,'Check-in Đà Lạt mùa hoa dã quỳ nở rộ! Không khí se se lạnh 17 độ C cùng ly sữa đậu nành nóng hổi thì còn gì tuyệt vời hơn. Ai chuẩn bị đi Đà Lạt điểm danh nào! 🌼🌸🧣 #DaLat #TravelVietnam','[\"https://images.unsplash.com/photo-1518495973542-4542c06a5843?w=800&auto=format&fit=crop\",\"https://images.unsplash.com/photo-1470246973918-29a93221c455?w=800&auto=format&fit=crop\",\"https://images.unsplash.com/photo-1519681393784-d120267933ba?w=800&auto=format&fit=crop\"]','2026-11-02 15:10:03','Đà Lạt, Lâm Đồng',NULL,'2026-11-07 15:10:03','active','public'),(37,12,'Sài Gòn về đêm luôn lung linh và tràn đầy sức sống. Dạo phố đi bộ Nguyễn Huệ ngắm đèn xe nhộn nhịp, tự nhiên thấy yêu thành phố này lạ kỳ. 🏙️✨ #SaigonByNight #NguyenHue','https://images.unsplash.com/photo-1519501025264-65ba15a82390?w=800&auto=format&fit=crop','2026-11-01 15:10:03','Phố đi bộ Nguyễn Huệ, Quận 1',NULL,'2026-11-07 15:10:03','active','public'),(38,13,'Một góc làm việc gọn gàng sẽ giúp tăng 200% hiệu suất làm việc! Hôm nay vừa setup thêm chiếc màn hình mới và vài chậu cây xanh nhỏ xinh. Mọi người thấy thế nào? 🪴🖥️ #DeskSetup #WorkspaceInspiration','https://images.unsplash.com/photo-1518455027359-f3f8164ba6bd?w=800&auto=format&fit=crop','2026-10-31 15:10:03','Home Workspace',NULL,'2026-11-07 15:10:03','active','friends'),(39,14,'“Hành trình vạn dặm bắt đầu từ một bước chân.” Cuốn sách mới đọc xong cuối tuần thật sự truyền cảm hứng để bắt đầu những mục tiêu mới cho tháng tới. 📖💡 #BookReview #SelfGrowth',NULL,'2026-10-30 15:10:03','Nhã Nam Book Nook','linear-gradient(135deg, #7c3aed 0%, #db2777 100%)','2026-11-07 15:10:03','active','public'),(40,15,'Chuyến roadtrip khám phá bán đảo Sơn Trà và cung đường đèo Hải Vân hùng vĩ! Cảm giác phóng xe máy giữa một bên là núi cao, một bên là biển xanh bao la thật khó tả. 🛵🌊 #HaiVanPass #DaNang','[\"https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800&auto=format&fit=crop\",\"https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800&auto=format&fit=crop\"]','2026-10-29 15:10:03','Đèo Hải Vân, Đà Nẵng',NULL,'2026-11-07 15:10:03','active','public'),(41,16,'Bữa cơm gia đình ấm cúng cuối tuần cùng ba mẹ. Đi xa mới thấy nhớ những món ăn mẹ nấu biết bao, sơn hào hải vị ngoài kia chẳng thể sánh bằng. ❤️🍲 #FamilyFirst #HomeSweetHome','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?w=800&auto=format&fit=crop','2026-10-28 15:10:03','Hải Phòng',NULL,'2026-11-07 15:10:03','active','friends'),(42,17,'Chúc mừng team vừa giành giải Nhất cuộc thi Hackathon sinh viên 2026! 48 giờ không ngủ, uống 10 ly cà phê nhưng kết quả hoàn toàn xứng đáng. Tự hào về mọi người nhiều lắm! 🏆🥇🎉 #Hackathon #TeamWork','https://images.unsplash.com/photo-1531482615713-2afd69097998?w=800&auto=format&fit=crop','2026-10-27 15:10:03','Trung tâm Đổi mới Sáng tạo Quốc gia (NIC)',NULL,'2026-11-07 15:10:03','active','public'),(43,18,'Tập gym 5 buổi/tuần duy trì được 6 tháng rồi, sức bền và tinh thần thay đổi rõ rệt. Không có con đường tắt, chỉ có sự kiên trì mỗi ngày. Let’s do this! 🏋️‍♂️🔥 #GymMotivation #HealthyLifestyle','https://images.unsplash.com/photo-1534438327276-14e5300c3a48?w=800&auto=format&fit=crop','2026-10-26 15:10:03','Elite Fitness',NULL,'2026-11-07 15:10:03','active','public'),(44,19,'Thưởng thức âm nhạc acoustic tại quán quen. Giữa thành phố bộn bề, có một nốt trầm lắng nghe giai điệu mộc mạc thế này là đủ an yên rồi. 🎶🎸 #AcousticNight #ChillVibes',NULL,'2026-10-25 15:10:03','Phố Cổ Hà Nội','linear-gradient(135deg, #0f172a 0%, #1e293b 50%, #334155 100%)','2026-11-07 15:10:03','active','public'),(45,20,'Hội An về đêm rực rỡ sắc màu đèn lồng và dòng sông Hoài thơ mộng. Thả một ngọn đèn hoa đăng cầu bình an và may mắn cho tất cả những người thân yêu. 🏮✨ #HoiAnAncientTown #VietnamTravel','https://images.unsplash.com/photo-1528127269322-539801943592?w=800&auto=format&fit=crop','2026-10-24 15:10:03','Phố cổ Hội An, Quảng Nam',NULL,'2026-11-07 15:10:03','active','public'),(46,21,'Chào đón thành viên 4 chân mới của gia đình! Em cún Poodle siêu nghịch ngợm tên Bơ, vừa về nhà đã cắn hỏng đôi dép của mình rồi 🐶❤️ Ai nuôi cún cho mình xin tips chăm sóc với! #PuppyLove #Poodle','https://images.unsplash.com/photo-1543466835-00a7907e9de1?w=800&auto=format&fit=crop','2026-10-23 15:10:03','TP. Hồ Chí Minh',NULL,'2026-11-07 15:10:03','active','public');
